// Original, self-contained specimens. Each entry is rendered inside a shadow root.
const BASE = `.sample{width:100%;height:100%;min-height:190px;display:grid;place-items:center;position:relative;overflow:hidden;box-sizing:border-box;font-family:Arial,'Hiragino Kaku Gothic ProN',Meiryo,sans-serif;color:#20211d;background:#f1f0e9;padding:22px}.sample *{box-sizing:border-box}.sample button,.sample input,.sample summary{font:inherit}.sample button,.sample summary,.sample label{touch-action:manipulation}.sample :focus-visible{outline:3px solid #6050bf;outline-offset:5px}.sample small{font-size:10px;line-height:1.5}.sample .editable{margin:0}.sample svg{max-width:100%;height:auto}`;
const P='https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/';
const C='https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/';
export const expressions=[];
function add(id,category,name,ja,description,use,tip,tags,html,css,source){expressions.push({id,category,name,ja,description,use,tip,tags,type:'static',html,css,code:`<style>\n${BASE}\n${css}\n</style>\n<div class="sample">\n${html}\n</div>`,source});}
const art=`<svg viewBox="0 0 240 160" role="img" aria-label="オレンジの太陽と紫の山の図形イラスト"><rect width="240" height="160" fill="#c2dfdb"/><circle cx="168" cy="46" r="29" fill="#ff7540"/><path d="M0 150 85 45 155 145 207 87 240 131V160H0Z" fill="#8c79bd"/><path d="m0 113 49-25 85 72H0Z" fill="#cedb70"/></svg>`;
const panels='<i>A</i><i>B</i><i>C</i><i>D</i><i>E</i><i>F</i>';
const cell='.sample i{font-style:normal;display:grid;place-items:center;background:var(--accent,#c9f537);border-radius:5px;font-size:16px;font-weight:700;min-width:0}.sample i:nth-child(2n){background:#b9a9e8}.sample i:nth-child(3n){background:#ff865d}';
// COLOR — five ways to understand color.
add('color-hex','color','HEX color','16進数のカラーコード','赤・緑・青の量を、6桁の16進数で指定します。','色を正確に共有するとき。','#RGBは各桁を重ねた#RRGGBBの省略形です。',['色','カラーコード','hex','緑'], '<div class="chip"><span class="editable">#C9F537</span><small>R 201 · G 245 · B 55</small></div>', '.sample .chip{width:190px;height:120px;background:#c9f537;border-radius:14px;display:flex;flex-direction:column;justify-content:space-between;padding:20px;font-weight:700}.sample .chip span{font-size:24px;font-family:monospace}',C+'hex-color');
add('color-alpha','color','Alpha transparency','色の透け具合','同じ色でも透明度によって、下の色との重なり方が変わります。','重なりや、写真の上に色を重ねる場面。','要素全体を薄くするopacityと、色だけに指定するalphaは作用が異なります。',['透明','透ける','alpha','重なる'], '<div class="swatches"><i>100%</i><i>65%</i><i>30%</i></div>', '.sample{background:repeating-conic-gradient(#fff 0% 25%,#dddcd6 0% 50%) 0/20px 20px}.sample .swatches{display:flex;gap:7px}.sample i{width:69px;height:104px;display:grid;place-items:center;font-style:normal;font-size:11px;background:rgb(140 100 210)}.sample i:nth-child(2){background:rgb(140 100 210/.65)}.sample i:nth-child(3){background:rgb(140 100 210/.3)}',C+'color_value/rgb');
add('color-hsl','color','HSL color','色相・彩度・明度','色相を回転させ、彩度と明度を分けて指定する色の表し方です。','色相をそろえたバリエーションをつくるとき。','HSLの明度が同じでも、色相ごとの見た目の明るさはそろいません。',['hsl','色相','彩度','明度'], '<div class="hues"><i>30°</i><i>90°</i><i>150°</i><i>210°</i><i>270°</i></div>', '.sample .hues{display:flex;width:100%;max-width:260px;height:118px}.sample i{flex:1;background:hsl(var(--h) 70% 70%);display:grid;align-items:end;padding-bottom:12px;text-align:center;font-style:normal;font-size:10px}.sample i:nth-child(1){--h:30}.sample i:nth-child(2){--h:90}.sample i:nth-child(3){--h:150}.sample i:nth-child(4){--h:210}.sample i:nth-child(5){--h:270}',C+'color_value/hsl');
add('color-oklch','color','OKLCH lightness','知覚を考慮した明るさ','色相と彩度を固定し、OKLCHの明度だけを段階的に変えます。','一つの色から濃淡のパレットを組むとき。','指定した色が画面で再現できる範囲を超えることもあります。',['oklch','パレット','濃淡','明るさ'], '<div class="tones"><i>35</i><i>48</i><i>61</i><i>74</i><i>87</i></div>', '.sample .tones{display:flex;gap:5px;width:100%;max-width:260px}.sample i{flex:1;height:112px;display:grid;align-items:end;text-align:center;padding:10px 0;font:11px monospace;background:oklch(var(--l) .09 290);color:white}.sample i:nth-child(1){--l:35%}.sample i:nth-child(2){--l:48%}.sample i:nth-child(3){--l:61%}.sample i:nth-child(4){--l:74%;color:#222}.sample i:nth-child(5){--l:87%;color:#222}',C+'color_value/oklch');
add('color-mix','color','Color mixing','CSSで色を混ぜる','二つの色を、指定した色空間と比率で混ぜます。','ブランドカラーから淡い背景色をつくるとき。','混ぜる色空間によって、中間色は変わります。',['color-mix','混色','パレット','中間色'], '<div class="mix"><i>100</i><b>+</b><i>50</i><b>+</b><i>20</i></div>', '.sample .mix{display:flex;align-items:center;gap:10px}.sample i{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;font:11px monospace;background:var(--accent,#c9f537)}.sample i:nth-of-type(2){background:color-mix(in oklab,var(--accent,#c9f537) 50%,white)}.sample i:nth-of-type(3){background:color-mix(in oklab,var(--accent,#c9f537) 20%,white)}.sample b{font-weight:400}',C+'color_value/color-mix');
// GRADIENT — five constructions.
add('gradient-linear','gradient','Linear gradient','線形グラデーション','一直線の方向に沿って色が移り変わります。','背景、帯、進行方向を感じさせる面。','角度と色の停止位置を分けて考えると調整しやすくなります。',['グラデーション','斜め','linear'], '<div class="tile"></div>', '.sample .tile{width:210px;height:140px;border-radius:18px;background:linear-gradient(135deg,#c9f537 0%,#a2d9b5 48%,#aa8fe9 100%)}',C+'gradient/linear-gradient');
add('gradient-radial','gradient','Radial gradient','放射状グラデーション','中心から外側へ色が変わる、円や楕円のグラデーションです。','光、柔らかな背景、視線を集めたい面。','中心位置をずらすだけでも、光源のような表現になります。',['光','放射','radial','丸'], '<div class="tile"></div>', '.sample .tile{width:210px;height:140px;border-radius:18px;background:radial-gradient(circle at 30% 30%,#ffffd5 0%,#eced90 20%,#bdb0e4 58%,#66568c 100%)}',C+'gradient/radial-gradient');
add('gradient-conic','gradient','Conic gradient','円錐形グラデーション','中心のまわりを一周する方向で色が移り変わります。','色相環、円グラフ風の背景、光沢の表現。','円周の始点と終点を同じ色にすると、継ぎ目が目立ちにくくなります。',['円錐','虹','色相環','conic'], '<div class="wheel"></div>', '.sample .wheel{width:140px;height:140px;border-radius:50%;background:conic-gradient(#ff9162,#e2ef7b,#86ccb7,#a0a4e6,#d898d1,#ff9162);box-shadow:inset 0 0 0 35px #ffffff22}',C+'gradient/conic-gradient');
add('gradient-repeat','gradient','Repeating gradient','繰り返すグラデーション','色の並びを反復して、縞やリズムをつくります。','パターン、区切り、進行中の表示。','色の切り替え位置をそろえると、ぼかしのない縞になります。',['ストライプ','縞','繰り返し','repeating'], '<div class="tile"></div>', '.sample .tile{width:210px;height:140px;border-radius:18px;background:repeating-linear-gradient(45deg,#252622 0 12px,#c9f537 12px 24px)}',C+'gradient/repeating-linear-gradient');
add('gradient-layered','gradient','Layered gradients','重ねてつくる色の雲','複数の放射状グラデーションを重ね、色の塊をつくります。','メッシュグラデーション風の抽象背景。','これは複数のCSS背景による表現で、専用のメッシュ構文ではありません。',['メッシュ','mesh','オーロラ','雲','柔らかい'], '<div class="tile"></div>', '.sample .tile{width:210px;height:140px;border-radius:18px;background:radial-gradient(at 10% 10%,#c9f537,transparent 65%),radial-gradient(at 90% 20%,#ff9973,transparent 60%),radial-gradient(at 60% 90%,#a786de,transparent 70%),#eac6d9}',P+'background-image');
// TYPE — five typographic controls.
add('type-tracking','type','Letter spacing','字間','文字どうしの間隔を調整し、密度やリズムを変えます。','短い見出し、ラベル、ロゴの検討。','長文では、見た目だけでなく読み進めやすさも確認します。',['字間','tracking','余白','文字'], '<div class="words"><b class="editable">expression</b><b class="editable">expression</b><b class="editable">expression</b></div>', '.sample .words{display:grid;gap:10px;text-align:center}.sample b{font-size:25px;letter-spacing:-.07em}.sample b:nth-child(2){letter-spacing:0}.sample b:nth-child(3){letter-spacing:.13em;font-size:20px}',P+'letter-spacing');
add('type-leading','type','Line height','行間','行の高さを変えると、文章の詰まり具合が変わります。','本文の読みやすさを整えるとき。','行間は文字サイズや一行の長さと一緒に調整します。',['行間','leading','読みやすさ','文章'], '<div class="columns"><p>見て、触って。<br>名前を覚えて。<br>表現を使おう。</p><p>見て、触って。<br>名前を覚えて。<br>表現を使おう。</p></div>', '.sample .columns{display:flex;gap:25px;align-items:start}.sample p{font-size:14px;margin:0;line-height:1.3}.sample p+ p{line-height:2.2;border-left:1px solid #aaa;padding-left:22px}',P+'line-height');
add('type-outline','type','Text outline','文字の輪郭線','文字の輪郭を線で描き、内部の塗りを抜きます。','大きな見出しや、背景を透かした文字。','細かな文字では輪郭線が読みづらくなるため、大きさも確認します。',['袋文字','アウトライン','輪郭','stroke'], '<b class="editable">good.</b>', '.sample b{font-size:clamp(45px,12vw,76px);font-weight:900;color:transparent;-webkit-text-stroke:2px #222;letter-spacing:-.08em}',P+'-webkit-text-stroke');
add('type-gradient','type','Gradient text','文字にグラデーション','背景のグラデーションを、文字の形で切り抜いて見せます。','短いタイトルや、色の変化を楽しむ文字。','背景画像が使えない場合の文字色も用意しておきます。',['グラデーション文字','カラフル','text'], '<b class="editable">good.</b>', '.sample b{font-size:76px;font-weight:900;letter-spacing:-.08em;color:#755caf}@supports(background-clip:text){.sample b{background:linear-gradient(100deg,#719331,#ac83dd,#f4794a);background-clip:text;-webkit-background-clip:text;color:transparent}}',P+'background-clip');
add('type-vertical','type','Vertical writing','縦書き','文字の進む方向を縦にし、行を横に並べます。','和文のタイトル、詩、編集的な画面。','英数字の向きはtext-orientationで調整できます。',['縦書き','和文','日本語','writing-mode'], '<div class="vertical"><p>あの表現に、</p><p>名前がつく。</p></div>', '.sample .vertical{writing-mode:vertical-rl;display:flex;flex-direction:column;gap:12px;height:142px}.sample p{font-family:serif;font-size:24px;letter-spacing:.12em;margin:0;line-height:1.4}',P+'writing-mode');
// LAYOUT — five spatial systems.
add('layout-grid','layout','CSS Grid','縦横をそろえるグリッド','行と列を定義し、二方向の整列をつくります。','カード一覧、誌面のような構成、複雑な整列。','列の比率とgapを先に決めると、構成が整理できます。',['グリッド','grid','整列','段組み'], '<div class="grid">'+panels+'</div>', '.sample .grid{width:220px;height:132px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}'+cell,P+'grid-template-columns');
add('layout-flex','layout','Flexbox','一方向に並べる','要素を一列に並べ、空き領域を分け合います。','ナビゲーション、ラベル列、カード内の整列。','折り返した各行の列幅をそろえたい場合はGridも比較します。',['flex','横並び','整列','伸縮'], '<div class="flex"><i>A</i><i>B</i><i>C</i></div>', '.sample .flex{display:flex;align-items:center;gap:9px;width:230px;height:140px}.sample i{flex:1;height:60px}.sample i:nth-child(2){flex:2;height:115px}'+cell,P+'flex');
add('layout-bento','layout','Spanning grid','大小を組み合わせるグリッド','一部の要素を複数の行や列にまたがって配置します。','情報の大きさに強弱をつけるカード構成。','見た目の配置を変えても、読む順序は自然に保ちます。',['bento','弁当','大小','grid','カード'], '<div class="bento"><i>A</i><i>B</i><i>C</i><i>D</i></div>', '.sample .bento{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,60px);gap:8px;width:230px}.sample i:first-child{grid-row:span 2}.sample i:last-child{grid-column:span 2}'+cell,P+'grid-column');
add('layout-overlap','layout','Layered composition','重ねて組む','位置をずらした要素を重ね、前後関係をつくります。','ビジュアルの編集、複数の写真や情報の関係づけ。','z-indexは重なりコンテキストの中で働きます。',['重なり','レイヤー','layer','z-index'], '<div class="stack"><i>01</i><i>02</i><i>03</i></div>', '.sample .stack{position:relative;width:210px;height:138px}.sample i{position:absolute;width:124px;height:86px;border:2px solid #222;border-radius:10px;top:0;left:0;padding:12px;font:700 18px monospace;background:#b9a9e8}.sample i:nth-child(2){left:41px;top:24px;background:#ff976a}.sample i:nth-child(3){left:83px;top:49px;background:var(--accent,#c9f537)}',P+'z-index');
add('layout-spacing','layout','Spacing scale','余白の尺度','一定の尺度で余白を決め、まとまりと間隔を整えます。','画面全体の間隔をそろえたいとき。','数値を共通化しても、内容の関係に応じて大小を使い分けます。',['余白','spacing','gap','尺度'], '<div class="spacing"><div><b>8</b><i></i></div><div><b>16</b><i></i></div><div><b>24</b><i></i></div><div><b>32</b><i></i></div></div>', '.sample .spacing{width:210px;display:grid;gap:12px}.sample .spacing div{display:flex;align-items:center;gap:12px}.sample b{width:22px;font:11px monospace}.sample i{height:16px;background:#222;width:32px}.sample div:nth-child(2)>i{width:64px}.sample div:nth-child(3)>i{width:96px}.sample div:nth-child(4)>i{width:128px}',P+'gap');
// SHAPE — four contours.
add('shape-radius','shape','Border radius','角丸','四隅の丸みを変えて、輪郭の印象を調整します。','カード、ボタン、写真の枠。','角丸の比率が大きいと、同じ指定でも要素の縦横比で形が変わります。',['角丸','radius','丸い','やわらかい'], '<div class="shapes"><i></i><i></i><i></i></div>', '.sample .shapes{display:flex;gap:10px}.sample i{width:61px;height:85px;background:var(--accent,#c9f537);border:2px solid #222}.sample i:nth-child(2){border-radius:16px}.sample i:nth-child(3){border-radius:45px}',P+'border-radius');
add('shape-blob','shape','Organic radius','有機的な輪郭','横方向と縦方向の角丸を別々に指定し、不均一な形をつくります。','有機的な背景や、親しみのある図形。','border-radiusはスラッシュの前後で横と縦の半径を分けられます。',['blob','有機的','しずく','丸み'], '<div class="blob"></div>', '.sample .blob{width:155px;height:135px;background:var(--accent,#c9f537);border-radius:35% 65% 70% 30% / 40% 35% 65% 60%;border:2px solid #222}',P+'border-radius');
add('shape-polygon','shape','Polygon clipping','多角形で切り抜く','頂点の座標を指定し、要素を多角形に切り抜きます。','バッジ、切り欠き、幾何学的な構成。','切り抜きは見た目を変えますが、通常のレイアウト領域はそのままです。',['clip-path','多角形','星','切り抜き'], '<div class="star">GOOD</div>', '.sample .star{width:150px;height:150px;background:#b8a6e5;clip-path:polygon(50% 0,61% 28%,85% 15%,72% 40%,100% 50%,72% 61%,85% 85%,61% 73%,50% 100%,39% 73%,15% 85%,28% 61%,0 50%,28% 40%,15% 15%,39% 28%);display:grid;place-items:center;font:900 18px Arial}',P+'clip-path');
add('shape-border','shape','Border styles','線の表情','実線、破線、点線など、輪郭線の種類を変えます。','領域の区切り、選択範囲、補助的な枠。','線の種類だけに意味を持たせず、ラベルも組み合わせます。',['border','点線','破線','線'], '<div class="borders"><i>solid</i><i>dashed</i><i>dotted</i></div>', '.sample .borders{display:flex;gap:12px}.sample i{width:64px;height:85px;display:grid;place-items:center;font:10px monospace;border:3px solid #222}.sample i:nth-child(2){border-style:dashed}.sample i:nth-child(3){border-style:dotted}',P+'border-style');
// SHADOW — four kinds of depth.
add('shadow-soft','shadow','Soft shadow','柔らかな影','ぼかした影を下に落とし、面が浮いて見えるようにします。','カードや、背景から少し離したい要素。','影の距離とぼかしを変えると、浮いている高さの印象が変わります。',['影','ふわっと','浮く','box-shadow'], '<div class="tile">Aa</div>', '.sample .tile{width:118px;height:104px;background:white;border-radius:16px;display:grid;place-items:center;font:600 40px Georgia;box-shadow:0 16px 30px -8px #29221e40}',P+'box-shadow');
add('shadow-hard','shadow','Hard shadow','輪郭のある影','ぼかしをなくし、くっきりした影をずらして置きます。','ポスター風のカードや、力強いボタン。','影にぼかしを指定しないと、形がはっきり残ります。',['硬い影','くっきり','ポップ','hard'], '<div class="tile">good.</div>', '.sample .tile{width:148px;height:94px;background:var(--accent,#c9f537);border:2px solid #222;display:grid;place-items:center;font:900 30px Arial;box-shadow:9px 9px 0 #222}',P+'box-shadow');
add('shadow-inset','shadow','Inset shadow','内側の影','要素の内側に影を描き、くぼみのような印象をつくります。','押し込まれた状態や、凹みの表現。','insetの有無で、影が要素の内側か外側か変わります。',['内側','くぼみ','inset','沈む'], '<div class="well"></div>', '.sample .well{width:140px;height:115px;border-radius:24px;background:#e2e1da;box-shadow:inset 8px 8px 16px #b8b7b0,inset -8px -8px 16px #fff}',P+'box-shadow');
add('shadow-glow','shadow','Outer glow','外側への発光','輪郭のまわりに色付きのぼかしを重ね、光を表現します。','暗い背景での強調や、光る輪郭。','発光を強めすぎると輪郭が読みにくくなるので比較します。',['光る','発光','ネオン','glow'], '<div class="light"></div>', '.sample{background:#242720}.sample .light{width:98px;height:98px;border-radius:50%;border:3px solid #ddff99;box-shadow:0 0 13px #c9f537,0 0 42px #c9f53788,inset 0 0 14px #c9f53766}',P+'box-shadow');
// TEXTURE — four surface treatments.
add('texture-glass','texture','Frosted glass','すりガラス','半透明の面の背後をぼかし、すりガラスのように見せます。','背景を感じさせながら情報を重ねたい場面。','filterは要素自身、backdrop-filterは背後に作用します。',['glass','ガラス','透ける','ぼかし'], '<div class="orb"></div><div class="glass">good<br><small>BACKDROP BLUR</small></div>', '.sample{background:#b7a6dc}.sample .orb{position:absolute;width:125px;height:125px;border-radius:50%;background:var(--accent,#c9f537);left:12%;top:12%}.sample .glass{width:185px;height:115px;padding:22px;background:#ffffff30;border:1px solid #ffffffa0;border-radius:16px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);font-size:27px;font-weight:700;line-height:1.2}',P+'backdrop-filter');
add('texture-halftone','texture','Halftone dots','網点のパターン','小さな点を一定間隔で並べ、印刷の網点を思わせる面をつくります。','ポスターや、質感を足す背景。','この例は均一なドット柄で、写真の階調を網点に変換する処理ではありません。',['網点','ドット','印刷','halftone'], '<div class="dots"><b>g</b></div>', '.sample .dots{width:204px;height:132px;background-color:#c9f537;background-image:radial-gradient(#20221e 1.2px,transparent 1.5px);background-size:6px 6px;display:grid;place-items:center}.sample b{font:900 100px Arial;color:#f1f0e9;line-height:1}',C+'gradient/radial-gradient');
add('texture-multiply','texture','Multiply blend','乗算で重ねる','前後の色を乗算し、重なる部分を暗く合成します。','インクの重なりや、色付きのレイヤー。','合成対象を区切りたいときはisolationも確認します。',['乗算','multiply','インク','重なる'], '<div class="blend"><i></i><i></i><i></i></div>', '.sample .blend{position:relative;width:210px;height:130px;isolation:isolate;background:white}.sample i{position:absolute;width:98px;height:98px;top:15px;border-radius:50%;background:#f48e66;mix-blend-mode:multiply;left:8px}.sample i:nth-child(2){left:57px;background:#a8cfea}.sample i:nth-child(3){left:106px;background:#e5e96b}',P+'mix-blend-mode');
add('texture-checker','texture','Checker pattern','市松模様','円錐形グラデーションをタイル状に繰り返し、格子をつくります。','透明部分の目印や、幾何学的な背景。','背景の大きさで、模様の細かさを調整します。',['市松','チェッカー','checker','格子'], '<div class="check"></div>', '.sample .check{width:210px;height:132px;border-radius:10px;background:repeating-conic-gradient(#b6a1e3 0% 25%,#eee9fa 0% 50%) 0/36px 36px}',C+'gradient/repeating-conic-gradient');
// IMAGE — local original geometric illustration, no network assets.
add('image-grayscale','image','Grayscale filter','白黒にする','画像の彩度を取り除き、グレースケールで表示します。','色を抑えた写真や、色の有無を比較するとき。','画像ファイルそのものを書き換えず、表示にフィルターを適用します。',['白黒','モノクロ','写真','grayscale'],art,'.sample svg{width:210px;border-radius:12px;filter:grayscale(1)}',C+'filter-function/grayscale');
add('image-hue','image','Hue rotation','色相を回転する','画像の色に色相回転のフィルターをかけます。','素材の色の変化を試すとき。','すべての色がHSL上で単純に同じ角度だけ移る処理ではありません。',['色相','hue-rotate','画像','色替え'],art,'.sample svg{width:210px;border-radius:12px;filter:hue-rotate(110deg)}',C+'filter-function/hue-rotate');
add('image-mask','image','Gradient mask','なだらかに隠す','マスクの透明度に応じて、画像の一部を徐々に隠します。','写真と背景を柔らかくつなぐ場面。','マスクの黒さではなく、通常は透明度が見える範囲を決めます。',['マスク','mask','消える','透ける'],art,'.sample svg{width:220px;mask-image:linear-gradient(to right,#000 30%,transparent);-webkit-mask-image:linear-gradient(to right,#000 30%,transparent)}',P+'mask-image');
add('image-crop','image','Circular crop','円形にトリミング','同じ素材を円の領域に切り抜いて見せます。','アバターや、図版の輪郭をそろえるとき。','重要な被写体が切れないか、中心位置も確認します。',['トリミング','丸','切り抜き','crop'],art,'.sample svg{width:170px;height:140px;clip-path:circle(62px at 50% 50%)}',P+'clip-path');
// SVG — four drawing properties.
add('svg-linecap','svg','Stroke linecap','線の端の形','線の端を、平ら・丸・四角に描き分けます。','線画アイコンの統一感を整えるとき。','roundとsquareは、線の座標より外側まで端が伸びます。',['線端','アイコン','round','linecap'], '<svg viewBox="0 0 230 140" role="img" aria-label="butt、round、squareの線端の比較"><g stroke="#252622" stroke-width="14"><path d="M35 30H165" stroke-linecap="butt"/><path d="M35 70H165" stroke-linecap="round"/><path d="M35 110H165" stroke-linecap="square"/></g><g font-size="10" fill="#222"><text x="180" y="33">butt</text><text x="180" y="73">round</text><text x="180" y="113">square</text></g></svg>', '.sample svg{width:230px}', 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Attribute/stroke-linecap');
add('svg-dash','svg','Stroke dasharray','線を破線にする','線と空白の長さを指定し、パスを破線で描きます。','点線のアイコン、経路、進行の表現。','円でも曲線でも、同じ線の指定が使えます。',['破線','点線','svg','dasharray'], '<svg viewBox="0 0 230 145" role="img" aria-label="間隔の異なる三つの破線"><g fill="none" stroke="#242521" stroke-width="4"><path d="M15 30H215" stroke-dasharray="12 6"/><path d="M15 70H215" stroke-dasharray="2 9" stroke-linecap="round"/><path d="M15 115Q115 25 215 115" stroke-dasharray="20 5 4 5"/></g></svg>', '.sample svg{width:230px}', 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Attribute/stroke-dasharray');
add('svg-bezier','svg','Bézier curve','ベジェ曲線','始点・終点と制御点で、滑らかな曲線を描きます。','アイコン、経路、図形の輪郭。','制御点は曲線が必ず通る点ではなく、曲がり方を決める点です。',['曲線','ベジェ','bezier','パス'], '<svg viewBox="0 0 240 140" role="img" aria-label="制御点とベジェ曲線"><path d="M25 110 65 0M215 30 165 140" stroke="#aaa" stroke-dasharray="3 4" fill="none"/><path d="M25 110C65 0 165 140 215 30" stroke="#242521" stroke-width="5" fill="none"/><g fill="#a78ad9"><circle cx="25" cy="110" r="7"/><circle cx="215" cy="30" r="7"/></g><g fill="#ff865d"><circle cx="65" cy="0" r="6"/><circle cx="165" cy="140" r="6"/></g></svg>', '.sample svg{width:230px;overflow:visible}', 'https://developer.mozilla.org/en-US/docs/Web/SVG/Tutorials/SVG_from_scratch/Paths');
add('svg-fill-rule','svg','Even-odd fill','重なる内側を抜く','輪郭をまたぐ回数の偶奇によって、塗る領域を決めます。','穴のある図形や、複数の輪郭からできたアイコン。','同じパスでもfill-ruleによって内側の塗り方が変わります。',['穴','塗り','evenodd','図形'], '<svg viewBox="0 0 180 150" role="img" aria-label="内側が抜けた二重の星形"><path d="M90 5 175 140H5Z M90 48 135 122H45Z" fill="#b39bdd" fill-rule="evenodd"/></svg>', '.sample svg{width:170px}', 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Attribute/fill-rule');
// UI — native, genuinely interactive HTML controls.
add('ui-details','ui','Disclosure','開閉する情報','見出しを押すと、補足情報を展開します。','FAQや、必要な人だけが読む解説。','detailsとsummaryで、基本の開閉をHTMLだけで実装できます。',['アコーディオン','開閉','faq','details'], '<details><summary>表現をひらく</summary><p>あの表現に、名前がつく。</p></details>', '.sample details{width:225px;background:white;border:1px solid #242521;border-radius:8px;padding:16px}.sample summary{cursor:pointer;font-size:14px;font-weight:700}.sample details p{font-size:12px;line-height:1.8;margin:14px 0 0;padding-top:12px;border-top:1px solid #ddd}', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/details');
add('ui-toggle','ui','Toggle switch','切り替えスイッチ','チェックボックスをスイッチとして見せ、状態を切り替えます。','有効・無効を切り替える設定。','見た目を変えても、入力要素とラベルの関係を保ちます。',['スイッチ','toggle','オンオフ','設定'], '<label class="switch"><input type="checkbox" aria-label="サンプル設定を有効にする"><span class="track"></span><b>試してみる</b></label>', '.sample .switch{display:flex;gap:14px;align-items:center;cursor:pointer;font-size:13px}.sample input{position:absolute;opacity:0;width:64px;height:36px}.sample .track{width:64px;height:36px;border-radius:50px;background:#c6c7bd;position:relative;transition:background .2s}.sample .track:before{content:"";position:absolute;left:4px;top:4px;width:28px;height:28px;border-radius:50%;background:white;transition:transform .2s}.sample input:checked+.track{background:#768f25}.sample input:checked+.track:before{transform:translateX(28px)}.sample input:focus-visible+.track{outline:3px solid #6050bf;outline-offset:4px}', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/input/checkbox');
add('ui-range','ui','Range input','連続値のスライダー','つまみを動かして、範囲内の値を選びます。','音量、強度、大きさなどの連続的な調整。','キーボードの矢印キーでも値を変更できます。',['スライダー','range','調整','つまみ'], '<label>強さを調整<input type="range" min="0" max="100" value="55" aria-label="サンプルの強さ"><span><small>0</small><small>100</small></span></label>', '.sample label{width:210px;font-size:13px;font-weight:700}.sample input{display:block;width:100%;margin:20px 0 7px;accent-color:#778e27}.sample span{display:flex;justify-content:space-between}', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/input/range');
add('ui-segmented','ui','Segmented selection','選択肢を並べる','排他的な選択肢を、横に並んだボタンのように見せます。','表示方法や、少数の条件の切り替え。','ラジオボタンのグループ名をそろえると、一つだけ選べます。',['セグメント','選択','radio','タブ風'], '<fieldset><legend>サンプルの表示密度</legend><label><input type="radio" name="density" checked><span>ゆったり</span></label><label><input type="radio" name="density"><span>きっちり</span></label></fieldset>', '.sample fieldset{border:0;display:flex;padding:5px;background:#dedfd6;border-radius:10px;gap:4px}.sample legend{font-size:12px;margin-bottom:13px;text-align:center}.sample label{position:relative;cursor:pointer}.sample input{position:absolute;opacity:0}.sample span{display:block;padding:12px 16px;font-size:12px;border-radius:6px}.sample input:checked+span{background:white;box-shadow:0 1px 4px #0002}.sample input:focus-visible+span{outline:3px solid #6050bf}', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/input/radio');
// INTERACTION — demonstrable states, no hidden JS.
add('interaction-hover','interaction','Hover elevation','触れると浮く','ポインターを乗せると、位置と影が変わります。','押せるカードやボタンへの補助的な反応。','タッチ端末にはホバーがないため、押したときの反応も用意します。',['hover','浮く','触れる','ホバー'], '<button type="button">touch me ↗</button>', '.sample button{border:1px solid #222;padding:19px 29px;border-radius:12px;background:var(--accent,#c9f537);font-weight:700;cursor:pointer;transition:transform .2s,box-shadow .2s}.sample button:hover,.sample button:focus-visible{transform:translateY(-7px);box-shadow:0 10px 0 #222}.sample button:active{transform:translateY(-2px);box-shadow:0 3px 0 #222}',P+'transition');
add('interaction-focus','interaction','Focus ring','操作位置を示す輪郭','キーボードで移動すると、現在操作している要素が輪郭でわかります。','キーボード操作を迷わず行える画面。','Tabキーでこのボタンへ移動すると輪郭を確認できます。',['focus','キーボード','フォーカス','アクセシビリティ'], '<div class="focus"><small>Tabキーで移動</small><button type="button">focus here</button></div>', '.sample .focus{text-align:center}.sample small{display:block;margin-bottom:15px}.sample button{background:#222;color:#fff;border:0;border-radius:8px;padding:17px 28px;cursor:pointer}.sample button:focus-visible{outline:4px solid #aa83de;outline-offset:7px}', 'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Selectors/:focus-visible');
add('interaction-scroll-snap','interaction','Scroll snap','区切りに吸着するスクロール','横へスクロールすると、カードの区切りで止まりやすくなります。','カード一覧や、小さなギャラリー。','操作の対象が伝わるよう、次のカードを少し見せます。',['スワイプ','横スクロール','snap','吸着'], '<div class="rail" tabindex="0" aria-label="横にスクロールするサンプル"><i>01</i><i>02</i><i>03</i><i>04</i></div>', '.sample .rail{display:flex;gap:12px;width:235px;max-width:100%;overflow-x:auto;scroll-snap-type:x mandatory;overscroll-behavior-x:contain;padding:8px 0 16px}.sample i{flex:0 0 150px;height:110px;scroll-snap-align:start;border-radius:12px;background:var(--accent,#c9f537);font:900 38px Arial;display:grid;place-items:center}.sample i:nth-child(2n){background:#b7a0e2}',P+'scroll-snap-type');
add('interaction-resize','interaction','Resizable region','大きさを変えられる領域','角のつまみをドラッグすると、領域の幅や高さが変わります。','レイアウトの確認や、入力欄の大きさ調整。','リサイズ操作の提供方法はブラウザや端末によって異なります。',['resize','ドラッグ','大きさ','サイズ変更'], '<div class="resizable" tabindex="0">角をドラッグ<small>RESIZE ME ↘</small></div>', '.sample .resizable{width:190px;height:108px;max-width:100%;max-height:155px;min-width:115px;min-height:80px;resize:both;overflow:auto;background:#bba9e2;border:2px solid #222;padding:18px;font-size:13px;font-weight:700}.sample small{display:block;margin-top:12px}',P+'resize');
// DATA — illustrative values are explicitly described.
add('data-bars','data','Bar chart','棒グラフ','棒の長さで、項目どうしの量を比べます。','カテゴリごとの数量を比較するとき。','これは説明用の値です。量を比べる棒グラフは、原則としてゼロを基準にします。',['棒グラフ','bar','比較','データ'], '<div class="chart" role="img" aria-label="例示データ A 35、B 80、C 55"><div><b>A</b><i style="width:35%">35</i></div><div><b>B</b><i style="width:80%">80</i></div><div><b>C</b><i style="width:55%">55</i></div><small>例示データ</small></div>', '.sample .chart{width:225px}.sample .chart>div{display:flex;align-items:center;margin:8px 0;gap:10px}.sample b{font:11px monospace;flex:0 0 12px}.sample i{display:block;background:var(--accent,#c9f537);height:24px;font:11px monospace;padding:6px}.sample small{display:block;color:#666;margin-top:9px}', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/img_role');
add('data-donut','data','Donut chart','ドーナツグラフ','円周を分割し、全体に対する割合を見せます。','少数の項目の構成比を伝えたいとき。','これは例示データです。割合は数値でも併記します。',['円グラフ','ドーナツ','割合','conic'], '<div class="donut" role="img" aria-label="例示データ 68パーセント"><b>68<small>%</small></b></div>', '.sample .donut{width:145px;height:145px;border-radius:50%;background:conic-gradient(#9980d1 0 68%,#dedbd0 68% 100%);display:grid;place-items:center}.sample b{width:106px;height:106px;border-radius:50%;background:#f1f0e9;display:flex;align-items:center;justify-content:center;font:700 35px Arial}.sample small{font-size:14px;margin-left:3px}',C+'gradient/conic-gradient');
add('data-sparkline','data','Sparkline','小さな折れ線グラフ','短い折れ線で、値の変化の傾向を示します。','表やカード内で、推移を簡潔に添えるとき。','数値の読み取りが重要なら、軸やラベルも用意します。',['推移','折れ線','sparkline','グラフ'], '<div class="spark"><small>例示データ · 7日間</small><svg viewBox="0 0 230 110" role="img" aria-label="20、40、32、67、48、79、90と推移する例示データ"><path d="M5 95 40 75 75 83 110 48 145 67 180 36 220 25V108H5Z" fill="#bda8e84d"/><path d="M5 95 40 75 75 83 110 48 145 67 180 36 220 25" fill="none" stroke="#8b6cbb" stroke-width="4" stroke-linejoin="round"/><circle cx="220" cy="25" r="6" fill="#8b6cbb"/></svg></div>', '.sample .spark{width:230px}.sample small{font-family:monospace;display:block;margin-bottom:8px}', 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/polyline');
add('data-heatmap','data','Heatmap','色で量を示す','セルの色の濃淡に、値の大小を対応させます。','時刻と曜日など、二つの軸に沿った分布。','色だけに頼らず、値や説明にもアクセスできるようにします。',['ヒートマップ','濃淡','分布','heatmap'], '<div class="heat" role="img" aria-label="5列3行の濃淡で分布を示す例示データ">'+[.2,.4,.7,.4,.2,.4,.8,1,.8,.5,.2,.5,.8,.5,.2].map(v=>`<i style="opacity:${v}"></i>`).join('')+'</div>', '.sample .heat{width:205px;display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.sample i{height:34px;background:#765ca8;border-radius:4px}',P+'opacity');
// 3D — CSS perspective, not WebGL.
add('three-perspective','three','CSS perspective','遠近感をつける','奥にある辺が小さく見えるように、要素へ遠近感を与えます。','立体的なカードや、奥行きのある構成。','perspectiveの距離が短いほど、遠近感が強くなります。',['3d','遠近','perspective','奥行き'], '<div class="stage"><div class="card">good.</div></div>', '.sample .stage{perspective:450px}.sample .card{width:150px;height:112px;background:#b8a0e3;border:2px solid #222;display:grid;place-items:center;font:900 30px Arial;transform:rotateY(-35deg) rotateX(15deg)}',P+'perspective');
add('three-cube','three','CSS cube','CSSで組む立方体','平面の要素を三次元空間に配置し、立方体に見せます。','構造や立体感を説明する小さな図形。','transform-styleで子要素の三次元配置を保ちます。',['立方体','cube','3d','立体'], '<div class="stage"><div class="cube"><i class="front">g</i><i class="right"></i><i class="top"></i></div></div>', '.sample .stage{perspective:500px}.sample .cube{width:95px;height:95px;position:relative;transform-style:preserve-3d;transform:rotateX(-22deg) rotateY(-33deg)}.sample i{position:absolute;width:95px;height:95px;border:1px solid #222;display:grid;place-items:center;font:900 52px Arial}.sample .front{background:#c9f537;transform:translateZ(47.5px)}.sample .right{background:#97b835;transform:rotateY(90deg) translateZ(47.5px)}.sample .top{background:#e2ff8c;transform:rotateX(90deg) translateZ(47.5px)}',P+'transform-style');
add('three-flip','three','Card flip','裏返して見せる','操作に合わせてカードを回転させ、裏面を見せます。','表と裏が対応する、少量の補足情報。','裏面はbackface-visibilityで隠し、重なって見えるのを防ぎます。',['裏返す','flip','回転','カード'], '<label class="flip"><input type="checkbox" aria-label="カードを裏返す"><span class="card"><b class="front">touch ↻</b><b class="back">hello!</b></span></label>', '.sample .flip{display:block;perspective:500px;cursor:pointer;width:164px;height:113px;position:relative}.sample input{position:absolute;opacity:0;width:100%;height:100%}.sample .card{display:block;width:100%;height:100%;position:relative;transform-style:preserve-3d;transition:transform .65s}.sample b{position:absolute;inset:0;display:grid;place-items:center;border-radius:12px;border:1px solid #222;backface-visibility:hidden;font-size:23px;background:#c9f537}.sample .back{background:#b8a0e3;transform:rotateY(180deg)}.sample input:checked+.card{transform:rotateY(180deg)}.sample input:focus-visible+.card{outline:3px solid #6050bf;outline-offset:5px}@media(prefers-reduced-motion:reduce){.sample .card{transition:none}}',P+'backface-visibility');
add('three-isometric','three','Isometric-style layers','等角投影風の重なり','斜め方向から見た面を重ねて、構造を立体的に見せます。','階層や、構成要素を説明する図。','この例はCSSの回転でつくる等角投影風の表現です。',['アイソメ','isometric','階層','レイヤー'], '<div class="layers"><i></i><i></i><i></i></div>', '.sample .layers{position:relative;width:120px;height:140px;transform:rotateX(52deg) rotateZ(-35deg);transform-style:preserve-3d}.sample i{position:absolute;inset:0;background:#b9a1e0;border:1px solid #222;transform:translateZ(-30px)}.sample i:nth-child(2){background:#ff956d;transform:translateZ(0)}.sample i:nth-child(3){background:#c9f537;transform:translateZ(30px)}',P+'transform');
// MEDIA — honest visual specimens, no implied audio/video playback.
add('media-waveform','media','Waveform graphic','波形のグラフィック','縦棒の高さを変え、音の波形を思わせる図形をつくります。','音声コンテンツの見た目を検討するとき。','これは静的な図形です。音声の解析や再生は行いません。',['波形','waveform','音','グラフィック'], '<div class="wave" aria-label="波形を模した静的な図形">'+[20,35,52,31,70,92,55,110,79,46,96,63,36,72,45,24,39].map(v=>`<i style="height:${v}px"></i>`).join('')+'</div>', '.sample .wave{display:flex;align-items:center;gap:5px;height:125px}.sample i{width:7px;background:#9980cb;border-radius:20px}',P+'align-items');
add('media-aspect','media','Aspect ratio','映像の縦横比','幅に対する高さの比率を決め、表示領域の形を保ちます。','動画枠、サムネイル、正方形の画像。','実際の動画とは別に、枠の縦横比を指定できます。',['アスペクト比','動画','16:9','aspect-ratio'], '<div class="frame"><span>16 / 9</span><small>映像枠のサンプル</small></div>', '.sample .frame{width:225px;aspect-ratio:16/9;background:#292b25;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#c9f537;border-radius:7px;gap:9px}.sample span{font:700 35px monospace}.sample small{color:#dbded2}',P+'aspect-ratio');
add('media-captions','media','Caption contrast','字幕の背景','文字の背後に半透明の面を敷き、映像と字幕を分けます。','動画や、写真に重ねる短いテキスト。','これは字幕の見た目の例です。動画字幕の実装ではtrack要素などを使います。',['字幕','caption','読みやすい','動画'], art+'<div class="caption">あの表現に、名前がつく。</div>', '.sample svg{width:235px;border-radius:8px}.sample .caption{position:absolute;bottom:40px;background:#000c;color:white;padding:6px 10px;font-size:12px;border-radius:3px}', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/track');
// STYLE — original compositions, not historical claims.
add('style-minimal','style','Minimal composition','要素を絞った構成','文字、線、余白を少数に絞り、関係をはっきりさせます。','情報の優先順位を整えた画面の検討。','要素を減らしたあとも、操作や意味の手がかりは残します。',['ミニマル','minimal','余白','静か'], '<div class="poster"><small>EXPRESSION / 01</small><b class="editable">Less,<br>but good.</b><span>→</span></div>', '.sample{background:#fff}.sample .poster{width:220px;height:145px;position:relative}.sample small{font:9px monospace;letter-spacing:.12em}.sample b{display:block;font-size:39px;letter-spacing:-.06em;line-height:1;margin-top:24px}.sample span{position:absolute;right:0;bottom:0;font-size:30px}',P+'letter-spacing');
add('style-swiss','style','Typographic grid','文字とグリッドの構成','強い文字の大小差と整列で、情報に秩序をつくります。','文字を主役にしたポスターや編集的な画面。','これはタイポグラフィとグリッドを使ったオリジナルの構成例です。',['スイス','swiss','タイポグラフィ','グリッド'], '<div class="poster"><small>EXPRESSION<br>STUDIES / 02</small><b>g.</b><p>FORM<br>FOLLOWS<br>CURIOSITY.</p></div>', '.sample{background:#ed623d}.sample .poster{width:215px;display:grid;grid-template-columns:1fr 1fr;align-items:start}.sample small{font:9px monospace;line-height:1.7}.sample b{grid-row:span 2;font:900 135px Arial;line-height:.9;letter-spacing:-.1em}.sample p{font:700 13px Arial;line-height:1.05;margin:25px 0 0}',P+'grid');
add('style-brutal','style','Bold borders','太い輪郭と強い配色','太い線、くっきりした影、大きな文字を組み合わせます。','勢いのあるカードや、主張の強い告知。','同じ要素の組み合わせでも、余白で読みやすさを整えられます。',['brutalism','ブルータリズム','ポップ','太い線'], '<div class="poster"><small>EXPRESSION / 03</small><b class="editable">GOOD<br>STUFF.</b><span>↗</span></div>', '.sample .poster{width:205px;height:139px;border:3px solid #222;background:#c9f537;box-shadow:7px 7px 0 #222;padding:15px;position:relative}.sample small{font:9px monospace}.sample b{font:900 33px Arial;line-height:.93;display:block;margin-top:14px;letter-spacing:-.06em}.sample span{position:absolute;right:12px;bottom:9px;font-size:37px}',P+'box-shadow');
add('style-editorial','style','Editorial contrast','書体にコントラストをつける','明朝系の大きな文字と、小さなラベルを組み合わせます。','雑誌のような読み物や、作品紹介。','書体の対比に加えて、大きさや余白の差も効きます。',['エディトリアル','editorial','雑誌','セリフ'], '<div class="poster"><small>THE EXPRESSION ISSUE</small><b class="editable">A good<br>feeling.</b><p>No. 04 — Notes on the web</p></div>', '.sample{background:#e8dfcf}.sample .poster{width:220px}.sample small{display:block;font:8px Arial;letter-spacing:.22em;border-bottom:1px solid #222;padding-bottom:9px}.sample b{font:italic 42px Georgia,serif;line-height:.95;display:block;letter-spacing:-.04em;margin-top:14px}.sample p{font:9px Arial;margin:13px 0 0}',P+'font-family');
add('style-retro','style','Retro interface','レトロな画面構成','等幅文字、平面的なボタン、強い枠線で画面を組みます。','昔のコンピューターを連想させる演出。','雰囲気を再現しながら、現在の操作性も確認します。',['レトロ','retro','ピクセル','コンピューター'], '<div class="window"><header><span>GOOD.EXE</span><b>×</b></header><div><p>HELLO, CREATOR_</p><button type="button">OK</button></div></div>', '.sample{background:#b5a5d6}.sample .window{width:213px;border:2px solid #222;background:#e4e2da;box-shadow:5px 5px 0 #222;font-family:monospace}.sample header{background:#222;color:#fff;display:flex;justify-content:space-between;padding:6px;font-size:10px}.sample .window>div{padding:17px}.sample p{font:11px monospace;margin:0 0 14px}.sample button{border:2px solid #222;background:#d5d7cb;box-shadow:2px 2px 0 #222;padding:4px 22px;font:11px monospace;cursor:pointer}.sample button:active{box-shadow:none;transform:translate(2px,2px)}',P+'font-family');
